create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, timezone text not null default 'Asia/Shanghai', updated_at timestamptz not null default now());
create table public.categories (id text primary key, user_id uuid not null references auth.users(id) on delete cascade, name text not null, color text not null default '#59a9d7', archived boolean not null default false, sort_order integer not null default 0, unique(user_id,name));
create table public.tags (id text primary key, user_id uuid not null references auth.users(id) on delete cascade, name text not null, archived boolean not null default false, unique(user_id,name));
create table public.recurrence_rules (id text primary key, user_id uuid not null references auth.users(id) on delete cascade, title text not null, frequency text not null check (frequency in ('daily','weekly','monthly')), weekdays integer[] not null default '{}', month_day integer check (month_day between 1 and 31), category_id text references public.categories(id), tag_ids text[] not null default '{}', estimated_minutes integer check (estimated_minutes > 0), active boolean not null default true, start_date date not null, end_date date);
create table public.tasks (id text primary key, user_id uuid not null references auth.users(id) on delete cascade, title text not null check (length(trim(title)) > 0), original_date date not null, planned_date date not null, category_id text references public.categories(id), status text not null check (status in ('todo','in_progress','completed','cancelled')), estimated_minutes integer check (estimated_minutes > 0), notes text not null default '', created_at timestamptz not null default now(), completed_at timestamptz, deleted_at timestamptz, recurrence_rule_id text references public.recurrence_rules(id));
create table public.task_tags (user_id uuid not null references auth.users(id) on delete cascade, task_id text not null references public.tasks(id) on delete cascade, tag_id text not null references public.tags(id), primary key(task_id,tag_id));
create table public.time_entries (id text primary key, user_id uuid not null references auth.users(id) on delete cascade, task_id text not null references public.tasks(id) on delete cascade, started_at timestamptz not null, ended_at timestamptz, duration_seconds integer check (duration_seconds > 0), source text not null check (source in ('timer','manual')), deleted_at timestamptz, check ((ended_at is null and duration_seconds is null) or (ended_at is not null and duration_seconds is not null)));
create table public.recurrence_occurrences (user_id uuid not null references auth.users(id) on delete cascade, rule_id text not null references public.recurrence_rules(id) on delete cascade, occurrence_date date not null, primary key(rule_id,occurrence_date));
create unique index one_running_timer_per_user on public.time_entries(user_id) where ended_at is null and deleted_at is null;
create index tasks_user_date_idx on public.tasks(user_id,planned_date) where deleted_at is null;
create index entries_user_start_idx on public.time_entries(user_id,started_at) where deleted_at is null;

alter table public.profiles enable row level security; alter table public.categories enable row level security; alter table public.tags enable row level security; alter table public.tasks enable row level security; alter table public.task_tags enable row level security; alter table public.time_entries enable row level security; alter table public.recurrence_rules enable row level security; alter table public.recurrence_occurrences enable row level security;
create policy "owner profiles" on public.profiles for all using (auth.uid()=id) with check (auth.uid()=id);
create policy "owner categories" on public.categories for all using (auth.uid()=user_id) with check (auth.uid()=user_id);
create policy "owner tags" on public.tags for all using (auth.uid()=user_id) with check (auth.uid()=user_id);
create policy "owner tasks" on public.tasks for all using (auth.uid()=user_id) with check (auth.uid()=user_id);
create policy "owner task tags" on public.task_tags for all using (auth.uid()=user_id) with check (auth.uid()=user_id);
create policy "owner time entries" on public.time_entries for all using (auth.uid()=user_id) with check (auth.uid()=user_id);
create policy "owner recurrence rules" on public.recurrence_rules for all using (auth.uid()=user_id) with check (auth.uid()=user_id);
create policy "owner recurrence occurrences" on public.recurrence_occurrences for all using (auth.uid()=user_id) with check (auth.uid()=user_id);
